using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using System.Text.Json;
namespace SimplePZMapmaker.Web.Services;
public sealed partial class GameAssetCatalog
{
 public sealed record Asset(string Id,string Category,string Name,string Group,string Facing,string? Grid,bool Blocking,bool Floor,Dictionary<string,string> Properties,string? Page,TexturePackIndex.Sprite? Sprite,string Source="game",string? ModId=null,string[]? Requirements=null);
 public sealed record Part(int Dx,int Dy,string Tile,byte Flags=0);
 public sealed record Placement(string Id,string Name,string Category,bool Blocking,List<Part> Parts,string Source="game",string? ModId=null,string[]? Requirements=null);
 private sealed record Atlas(string Path,TexturePackIndex.Page Page,string Fingerprint);
 private readonly string cache;private readonly object sync=new();private Dictionary<string,Asset> items=new(StringComparer.Ordinal);private Dictionary<string,Atlas> atlases=[];
 public string GamePath {get;private set;}public string? Error {get;private set;}public bool Ready=>items.Count>0;public int Count=>items.Count;
 public GameAssetCatalog(string workspace,string gamePath){cache=Path.Combine(workspace,"work","assets");GamePath=gamePath;try{var config=Path.Combine(cache,"source.json");if(File.Exists(config))GamePath=JsonSerializer.Deserialize<Dictionary<string,string>>(File.ReadAllText(config))?.GetValueOrDefault("gamePath")??gamePath;Refresh(GamePath,false);RestoreMods();}catch(Exception e) when(e is ArgumentException or IOException or UnauthorizedAccessException or JsonException){Error=e.Message;}}
 public object Status()=>new{ready=Ready,count=Count,gamePath=GamePath,error=Error,categories=items.Values.GroupBy(a=>a.Category).Select(g=>new{id=g.Key,count=g.Count()}).OrderBy(g=>g.id)};
 public object Search(string? q,string? category,int offset=0,int limit=72,string? source=null){lock(sync)return SearchCore(q,category,offset,limit,source);}
 private object SearchCore(string? q,string? category,int offset,int limit,string? source){q=(q??"").Trim();if(q.Length>120||offset<0||offset>200000||limit is <1 or >120)throw new ArgumentException("Проверьте поиск и страницу каталога.");var list=items.Values.Where(a=>(string.IsNullOrEmpty(source)||source=="game"&&a.ModId is null||source=="mod"&&a.ModId is not null||a.ModId==source)&&(string.IsNullOrEmpty(category)||a.Category==category)&&(q.Length==0||a.Id.Contains(q,StringComparison.OrdinalIgnoreCase)||a.Name.Contains(q,StringComparison.OrdinalIgnoreCase)||a.Group.Contains(q,StringComparison.OrdinalIgnoreCase))).OrderBy(a=>a.Id).ToArray();return new{total=list.Length,offset,limit,items=list.Skip(offset).Take(limit).Select(a=>new{a.Id,a.Category,a.Name,a.Group,a.Facing,a.Grid,a.Blocking,a.Floor,a.Page,a.Sprite,a.Source,a.ModId,a.Requirements,pageWidth=a.Page is not null?atlases[a.Page].Page.Width:0,pageHeight=a.Page is not null?atlases[a.Page].Page.Height:0,water=a.Properties.ContainsKey("water"),roles=Roles(a),placeable=CanPlace(a.Id)})};}
 public Asset Get(string id)=>items.GetValueOrDefault(id)??throw new ArgumentException("Тайл отсутствует в выбранной установке игры: "+id);
 public object Pair(string id,string role){lock(sync)return PairCore(id,role);}
 private object PairCore(string id,string role){var a=Get(id);if(role=="roof"){var prefix=Prefix(id);if(!Regex.IsMatch(prefix,@"^roofs_30_[0-9]{2}$")||Enumerable.Range(0,30).Where(i=>i%8<6).Any(i=>!items.TryGetValue(prefix+"_"+i,out var tile)||tile.Category!="roofs"))throw new ArgumentException("Для генератора нужен полный набор крыши 30°.");return new{tileset=prefix};}
  string Property(string face)=>role switch{"wall"=>"Wall"+face,"door"=>"door"+face,"window"=>"window"+face,_=>throw new ArgumentException("Неизвестная роль тайла.")};
  bool Matches(Asset b,string face)=>b.Properties.ContainsKey(Property(face))&&(role!="wall"||!b.Properties.Keys.Any(p=>p.StartsWith("Window",StringComparison.Ordinal)||p.StartsWith("DoorWall",StringComparison.Ordinal)));
  var n=items.Values.Where(b=>Prefix(b.Id)==Prefix(id)&&Matches(b,"N")&&Number(b.Id)/16==Number(id)/16).OrderBy(b=>Math.Abs(Number(b.Id)-Number(id))).FirstOrDefault();var w=items.Values.Where(b=>Prefix(b.Id)==Prefix(id)&&Matches(b,"W")&&Number(b.Id)/16==Number(id)/16).OrderBy(b=>Math.Abs(Number(b.Id)-Number(id))).FirstOrDefault();if(n is null||w is null)throw new ArgumentException("У тайла нет совместимой пары север/запад.");return new{n=n.Id,w=w.Id};
 }
 private static string[] Roles(Asset a){var roles=new List<string>();if(a.Floor)roles.Add("floor");if(a.Properties.ContainsKey("WallN")||a.Properties.ContainsKey("WallW"))if(!a.Properties.Keys.Any(p=>p.StartsWith("Window",StringComparison.Ordinal)||p.StartsWith("DoorWall",StringComparison.Ordinal)))roles.Add("wall");if(a.Properties.ContainsKey("doorN")||a.Properties.ContainsKey("doorW"))roles.Add("door");if(a.Properties.ContainsKey("windowN")||a.Properties.ContainsKey("windowW"))roles.Add("window");if(a.Id.StartsWith("roofs_30_"))roles.Add("roof");return roles.ToArray();}
 public object Describe(IEnumerable<string> ids){lock(sync)return DescribeCore(ids);}
 private object DescribeCore(IEnumerable<string> ids){var values=ids.Distinct().ToArray();if(values.Length>2000)throw new ArgumentException("Слишком много тайлов для предпросмотра.");return values.Where(items.ContainsKey).Select(id=>{var a=items[id];return new{a.Id,a.Page,a.Sprite,a.Source,a.ModId,a.Requirements,pageWidth=a.Page is not null?atlases[a.Page].Page.Width:0,pageHeight=a.Page is not null?atlases[a.Page].Page.Height:0};}).ToArray();}
 public Placement PlacementFor(string id){lock(sync)return PlacementCore(id);}
 private Placement PlacementCore(string id){
  var a=Get(id);if(a.Floor||a.Category is "walls" or "doors" or "windows" or "roofs" or "stairs")throw new ArgumentException("Этот ресурс используется для пола, стены, проёма или крыши.");
  if(a.Properties.ContainsKey("WallN")||a.Properties.ContainsKey("WallW")||a.Properties.ContainsKey("attachedN")||a.Properties.ContainsKey("attachedW"))throw new ArgumentException("Настенные ресурсы требуют соответствующей стены; выберите напольный объект.");
  if(a.Grid is null)return new(a.Id,a.Name,a.Category,a.Blocking,[new(0,0,a.Id,Flags(a))],a.Source,a.ModId,a.Requirements??[]);
  var group=items.Values.Where(b=>b.Group==a.Group&&b.Name==a.Name&&b.Facing==a.Facing&&b.Grid is not null&&Prefix(b.Id)==Prefix(a.Id)).OrderBy(b=>Number(b.Id));var segments=new List<List<Asset>>();var current=new List<Asset>();var positions=new HashSet<string>();foreach(var b in group){if(!positions.Add(b.Grid!)){segments.Add(current);current=[];positions=[];positions.Add(b.Grid!);}current.Add(b);}segments.Add(current);var selected=segments.Single(s=>s.Any(b=>b.Id==a.Id));
  var parts=selected.Select(b=>{var xy=b.Grid!.Split(',');return new Part(int.Parse(xy[0]),int.Parse(xy[1]),b.Id,Flags(b));}).ToList();var width=parts.Max(p=>p.Dx)+1;var height=parts.Max(p=>p.Dy)+1;if(width is <1 or >8||height is <1 or >8||parts.Count!=width*height||parts.Count>32||parts.Any(p=>p.Dx<0||p.Dy<0))throw new ArgumentException("У ресурса неполная сетка спрайтов; выберите другой вариант.");return new(a.Id,a.Name,a.Category,selected.Any(b=>b.Blocking),parts,a.Source,a.ModId,a.Requirements??[]);
 }
 private bool CanPlace(string id){try{PlacementFor(id);return true;}catch(Exception e) when(e is ArgumentException or FormatException or InvalidOperationException){return false;}}
 public void Refresh(string path,bool save=true){lock(sync){
  var root=ModRegistry.SafePath(path);if(!Directory.Exists(Path.Combine(root,"media","texturepacks")))throw new ArgumentException("Укажите папку Project Zomboid с media/texturepacks.");
  var definitions=Path.Combine(root,"media","newtiledefinitions.tiles.txt");if(!File.Exists(definitions)||new FileInfo(definitions).Length>16*1024*1024)throw new ArgumentException("Не найден справочник тайлов Build 42.");
  var next=new Dictionary<string,Asset>(StringComparer.Ordinal);var nextAtlases=new Dictionary<string,Atlas>();var files=new[]{definitions,"tiledefinitions_erosion.tiles.txt","jumbo_trees.tiles.txt","jumbo_trees_big.tiles.txt"}.Select(file=>Path.IsPathRooted(file)?file:Path.Combine(root,"media",file)).Where(File.Exists);var inputs=files.ToArray();if(inputs.Any(file=>new FileInfo(file).Length>16*1024*1024))throw new ArgumentException("Справочник тайлов слишком велик.");var text=string.Join('\n',inputs.Select(File.ReadAllText));
  foreach(Match m in Regex.Matches(text,@"// ([a-zA-Z0-9_]+_\d+)\r?\n\s*tile\s*\{([^}]+)\}",RegexOptions.None,TimeSpan.FromSeconds(8))){var props=new Dictionary<string,string>();foreach(var line in m.Groups[2].Value.Split('\n')){var split=line.IndexOf('=');if(split>=0)props[line[..split].Trim()]=line[(split+1)..].Trim();}var id=m.Groups[1].Value;var floor=props.ContainsKey("solidfloor");var category=Category(id,props);next[id]=new(id,category,props.GetValueOrDefault("CustomName",id),props.GetValueOrDefault("GroupName",""),props.GetValueOrDefault("Facing",""),props.GetValueOrDefault("SpriteGridPos"),props.ContainsKey("solid")||props.ContainsKey("solidtrans")||props.ContainsKey("BlocksPlacement")||props.ContainsKey("tree")||props.ContainsKey("collideN")||props.ContainsKey("collideW"),floor,props,null,null);}
  foreach(var file in new[]{"Tiles2x.pack","Tiles2x.floor.pack","Overlays2x.pack","Overlays2x.floor.pack","JumboTrees2x.pack","JumboTreesBigs2x.pack"}){
   var full=Path.Combine(root,"media","texturepacks",file);if(!File.Exists(full))continue;var fingerprint=Fingerprint(full);using var stream=File.OpenRead(full);foreach(var page in TexturePackIndex.Read(stream,file)){
    var key=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(full+fingerprint+page.Offset)))[..24].ToLowerInvariant();nextAtlases[key]=new(full,page,fingerprint);foreach(var sprite in page.Sprites)if(next.TryGetValue(sprite.Name,out var a))next[sprite.Name]=a with{Page=key,Sprite=sprite};
   }
  }
  var merged=MergeMods(next,nextAtlases,activeMods);gameItems=next;gameAtlases=nextAtlases;items=merged.Items;atlases=merged.Atlases;modDiagnostics=discoveryDiagnostics.Concat(merged.Diagnostics).ToList();GamePath=root;Error=null;Directory.CreateDirectory(cache);if(save)File.WriteAllText(Path.Combine(cache,"source.json"),JsonSerializer.Serialize(new{gamePath=root}));
 }}
 public byte[] Page(string key){lock(sync)return PageCore(key);}
 private byte[] PageCore(string key){if(!atlases.TryGetValue(key,out var atlas))throw new ArgumentException("Атлас не найден.");if(Fingerprint(atlas.Path)!=atlas.Fingerprint)throw new ArgumentException("Игра обновилась. Обновите каталог ресурсов.");var target=Path.Combine(cache,key+".png");if(File.Exists(target))return File.ReadAllBytes(target);using var stream=File.OpenRead(atlas.Path);stream.Position=atlas.Page.Offset;var bytes=new byte[atlas.Page.Length];stream.ReadExactly(bytes);var temp=target+"."+Guid.NewGuid().ToString("N")+".tmp";File.WriteAllBytes(temp,bytes);File.Move(temp,target,true);return bytes;}
 private static string Fingerprint(string path){var info=new FileInfo(path);return info.Length+":"+info.LastWriteTimeUtc.Ticks;}
 public static byte Flags(Asset a)=>(byte)((!a.Properties.ContainsKey("tree")&&(a.Properties.ContainsKey("solid")||a.Properties.ContainsKey("solidtrans"))?1:0)|(a.Properties.ContainsKey("collideN")?2:0)|(a.Properties.ContainsKey("collideW")?4:0));
 private static string Prefix(string id)=>id[..id.LastIndexOf('_')];private static int Number(string id)=>int.Parse(id[(id.LastIndexOf('_')+1)..]);
 private static string Category(string id,Dictionary<string,string> p)=>id.StartsWith("roofs_")?"roofs":p.ContainsKey("solidfloor")?"floors":p.ContainsKey("doorN")||p.ContainsKey("doorW")?"doors":p.ContainsKey("windowN")||p.ContainsKey("windowW")?"windows":p.ContainsKey("WallN")||p.ContainsKey("WallW")||id.StartsWith("walls_")?"walls":id.StartsWith("carpentry_02_")&&Number(id) is >=80 and <=99?"stairs":id.StartsWith("vegetation_")||p.ContainsKey("tree")?"vegetation":id.StartsWith("fencing_")?"fences":id.StartsWith("lighting_")?"lighting":id.StartsWith("furniture_")?"furniture":id.StartsWith("appliances_")?"appliances":id.StartsWith("street_decoration_")||id.StartsWith("location_")?"decoration":"other";
}
